package fr.gemsofrod.encyclopedie.data

/** Traduzioni italiane del nome, dei testi descrittivi e dell'interesse gioielliero delle conchiglie. */
object CoquillageTranslationsIt {
    val data: Map<String, CoquillageTranslation> = mapOf(
        "coquillage-ormeau" to CoquillageTranslation(
            nom = "Abalone",
            descriptionCourte = "La conchiglia di un grande gasteropode marino, rivestita da una madreperla dai riflessi cangianti molto apprezzata in gioielleria.",
            descriptionLongue = "L'abalone è un mollusco gasteropode erbivoro che vive fissato alle rocce in acque fredde e ricche di alghe. La sua conchiglia appiattita a forma d'orecchio, forata da una fila di aperture respiratorie, nasconde una madreperla dall'iridescenza eccezionale che va dal blu-verde al viola a seconda dell'angolo della luce — un gioco di colori dovuto alla struttura microscopica a lamelle di aragonite che diffrange la luce, non a un pigmento. Molto usata in tarsia e nella bigiotteria.",
